                from.SendMessage("Spawning {0}...", filename);
                m_MapOverride = -1;
                m_IDOverride = -1;
                m_MinTimeOverride = -1;
                m_MaxTimeOverride = -1;
                using (StreamReader ip = new StreamReader(monster_path))
