            int map = Utility.ToInt32(sm);
            //MinTime
            string samintime = smintime;
            if (smintime.Contains("s") || smintime.Contains("m") || smintime.Contains("h"))
                samintime = smintime.Remove(smintime.Length - 1);
            double dmintime = Utility.ToDouble(samintime);
